import math

def test_perfect():
    assert solution.log_likelihood([1.0, 0.0], [1, 0]) == 0.0

def test_matches_likelihood():
    probs, labels = [0.9, 0.2, 0.6], [1, 0, 1]
    assert abs(solution.log_likelihood(probs, labels) - math.log(solution.likelihood(probs, labels))) < 1e-9

def test_small_probs_no_underflow():
    probs, labels = [1e-4, 1 - 1e-4], [1, 0]
    assert solution.log_likelihood(probs, labels) < -9

def test_label_zero():
    assert abs(solution.log_likelihood([0.25], [0]) - math.log(0.75)) < 1e-12

def test_invalid_prob():
    try:
        solution.log_likelihood([1.5], [1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.log_likelihood([0.5], [1]), float)
